        let tok = test_tokenizer();
        let mut ids = tok.encode("hi");
        ids.push(1);
        let (_s, fin_eot, _) = drive_qwen_ids(&ids, AssistantPrefix::Plain);
        assert!(fin_eot.decoded_eot);
